  --destructive-foreground: oklch(0.98 0 0);
  --success: oklch(0.75 0.17 150);
  --border: oklch(0.56 0.045 184 / 0.36);
  --input: oklch(0.49 0.04 185 / 0.55);
  --ring: oklch(0.68 0.17 52);
  --chart-1: oklch(0.68 0.17 52);
  --chart-2: oklch(0.75 0.15 78);
  --chart-3: oklch(0.7 0.09 150);
  --chart-4: oklch(0.68 0.1 20);
  --chart-5: oklch(0.7 0.07 290);
  --sidebar: oklch(0.19 0.004 260);
  --sidebar-foreground: oklch(0.93 0.005 80);
  --sidebar-primary: oklch(0.8 0.1 78);
  --sidebar-primary-foreground: oklch(0.18 0.01 78);
  --sidebar-accent: oklch(0.25 0.005 260);
  --sidebar-accent-foreground: oklch(0.93 0.005 80);
