.cycle-tl-return {
  width: 2px;
  flex: 1;
  background: var(--primary);
  opacity: 0.5;
  min-height: 24px;
  position: relative;
}

.cycle-tl-return::after {
  content: "↻";
  position: absolute;
  bottom: -1.2rem;
  left: 50%;
  transform: translateX(-50%);
  color: var(--primary);
  font-size: 1.2rem;
  opacity: 0.7;
}

