export type ConfiguratorMode = "network" | "platform" | "dependencies";

export interface GraphLayers {
  network: boolean;
  features: boolean;
  relationships: boolean;
  clusters: boolean;
  sector: boolean;
  theme: boolean;
  hub: boolean;
}

export interface ConfiguratorState {
