    requirement.outcome.trim() ? `${labels.outcome}: ${requirement.outcome.trim()}` : "",
    requirement.constraints.trim()
      ? `${labels.constraints}: ${requirement.constraints.trim()}`
      : "",
  ]
    .filter(Boolean)
    .join("\n");
}

